DM.def('run-queue', (r, c) => {
  const G = [
    { t:'Research three competitors', subs:[['Read their pricing pages','3/3'],['Compared plans and limits','5 gaps']] },
    { t:'Draft the launch email', subs:[['Pulled the new features','Done'],['Wrote two subject lines','Done'],['Sent a test to the team','', 'fail']] },
    { t:'Update the help centre', subs:[['Billing questions','4 articles'],['Inviting your team','2 articles']] }
  ];
  const list = $('.rq-list', r), all = $('.rq-all', r);
  let compact = false, doneCount = 0;
  G.forEach((g, gi) => {
    const el = html(`<div class="rq-g"><div class="rq-gh"><span class="g"><span class="dot" style="color:var(--faint)"></span></span><span>${g.t}</span><span class="m">Queued</span></div><div class="rq-bar"><i></i></div><div class="fold"><div>${g.subs.map(s => `<div class="rq-sub wait"><span class="g"><span class="dot" style="color:var(--faint);width:5px;height:5px"></span></span><span>${s[0]}</span><span class="m"></span></div>`).join('')}</div></div></div>`);
    g.el = el; list.appendChild(el);
  });
  seg($('.seg2', r), v => { compact = v === 'compact'; G.forEach(g => $('.fold', g.el).classList.toggle('shut', compact)); });
  const setG = (g, glyph, m) => { $('.rq-gh .g', g.el).innerHTML = glyph; swap($('.rq-gh .m', g.el), m); };
  const ok = `<span style="color:var(--ok)">${I('check','xs')}</span>`;
  async function runGroup(g){
    setG(g, '<span class="spin" style="color:var(--fg)"></span>', 'Running');
    const subs = $$('.rq-sub', g.el), bar = $('.rq-bar i', g.el);
    for (let i = 0; i < subs.length; i++){
      const s = subs[i]; s.classList.remove('wait'); $('.g', s).innerHTML = '<span class="spin" style="width:10px;height:10px"></span>';
      await c.wait(900);
      if (g.subs[i][2] === 'fail' && !g.retried){
        $('.g', s).innerHTML = `<span style="color:var(--bad)">${I('x','xs')}</span>`;
        $('.m', s).innerHTML = '<button class="rq-retry">Retry</button>';
        setG(g, `<span style="color:var(--bad)">${I('alert','xs')}</span>`, '1 step failed');
        await new Promise(res => { $('.rq-retry', s).onclick = res; });
        g.retried = true; i--; $('.m', s).textContent = ''; setG(g, '<span class="spin" style="color:var(--fg)"></span>', 'Retrying'); continue;
      }
      bar.style.width = ((i + 1) / subs.length * 100) + '%';
      $('.g', s).innerHTML = ok; swap($('.m', s), g.subs[i][1] || 'Done');
    }
    setG(g, ok, 'Done'); doneCount++; swap(all, doneCount + ' of 3 done');
  }
  c.run(async () => { await c.wait(600); for (const g of G) await runGroup(g); });
});
